head.b:skin:
body{margin:0;background:#f1f4f9;color:#1c2433;font:14px/1.5 'Noto Sans Devanagari',system-ui,sans-serif}
*{box-sizing:border-box}a{color:inherit;text-decoration:none}img{max-width:100%}
.navbar,.Navbar,#navbar-iframe{display:none!important}
.w{max-width:1500px;margin:0 auto;padding:0 20px}
.top{background:#0b2a63;color:#fff;font-size:13px}.top .w{display:flex;justify-content:space-between;align-items:center;height:34px;gap:10px}
.head{background:#fff}.head .w{display:flex;align-items:center;justify-content:space-between;gap:16px;padding-top:12px;padding-bottom:12px;flex-wrap:wrap}
.logo{display:flex;align-items:center;gap:12px}.logo i{width:56px;height:56px;border-radius:50%;background:#0b2a63;color:#fff;display:grid;place-items:center;font:800 20px sans-serif;border:3px solid #7fa6e8}
.logo h1{margin:0;font-size:40px;line-height:1.1;color:#e11d2e;font-weight:800}.logo small{color:#444}
.search{display:flex;width:300px;max-width:100%}.search input{flex:1;min-width:0;border:1px solid #e3e7ef;padding:10px;border-radius:6px 0 0 6px;font:inherit}.search button{background:#0b2a63;color:#fff;border:0;padding:0 14px;border-radius:0 6px 6px 0;cursor:pointer}
nav{background:#0b2a63}nav .w{display:flex;overflow-x:auto}nav a{color:#fff;font-weight:600;padding:12px 14px;white-space:nowrap}nav a.on{background:#e11d2e}nav a:hover{background:#163f8f}
.brk{background:#fff;border-bottom:1px solid #e3e7ef}.brk .w{display:flex;align-items:center;gap:14px;height:46px}.tag{background:#e11d2e;color:#fff;font-weight:700;padding:6px 16px;border-radius:20px;white-space:nowrap}
.tick{flex:1;overflow:hidden;white-space:nowrap;color:#e11d2e}.tick div{display:inline-block;padding-left:100%;animation:tk 45s linear infinite}@keyframes tk{to{transform:translateX(-100%)}}
@media(prefers-reduced-motion:reduce){.tick div{animation:none;padding:0}}
.g{display:grid;grid-template-columns:290px 1fr 340px;gap:16px;padding-top:16px;padding-bottom:30px}
.box{background:#fff;border-radius:6px;box-shadow:0 1px 3px rgba(20,40,80,.1);padding:12px;margin-bottom:16px}
.st,.box h2,.box .widget h2{font-weight:800;font-size:17px;color:#0b2a63;border-left:4px solid #e11d2e;padding-left:8px;margin:0 0 10px}
.badge{display:inline-block;color:#fff;font-size:11px;font-weight:600;padding:0 7px;border-radius:3px}.tm{color:#6b7385;font-size:12px}
.im{display:grid;place-items:center;color:rgba(255,255,255,.85);font-weight:800;font-size:28px;border-radius:3px;object-fit:cover;width:100%;height:100%;background-size:cover;background-position:center}
.li{display:flex;gap:10px;padding:9px 0;border-bottom:1px solid #e3e7ef}.li:last-child{border:0}.li .im{width:84px;height:62px;flex:none;font-size:20px}.li h4{margin:2px 0;font-size:13px;font-weight:500}
.mainrow{display:grid;grid-template-columns:1.9fr 1fr;gap:12px;margin-bottom:16px}
.hero{position:relative;display:block;min-height:290px;border-radius:6px;overflow:hidden;color:#fff}.hero .im{position:absolute;inset:0;border-radius:0;font-size:90px}
.hero:after{content:"";position:absolute;inset:0;background:linear-gradient(transparent 35%,rgba(0,0,0,.82))}.hero .tx{position:absolute;z-index:1;left:18px;right:18px;bottom:14px}.hero h2{margin:6px 0;font-size:24px;line-height:1.4;color:#fff;border:0;padding:0}.hero .tm{color:#dde}
.side3 .li{background:#fff;padding:8px;margin-bottom:4px;border-radius:4px}
.cards{display:grid;grid-template-columns:repeat(auto-fill,minmax(160px,1fr));gap:12px}.card{border:1px solid #e3e7ef;border-radius:4px;overflow:hidden;background:#fff}.card .im{height:90px;border-radius:0}.card .b{padding:8px}.card h4{margin:4px 0;font-size:13px}
.cats{display:grid;grid-template-columns:repeat(auto-fill,minmax(88px,1fr));gap:8px}.cats a{color:#fff;text-align:center;font-weight:600;padding:14px 4px;border-radius:5px}
.soc{display:grid;grid-template-columns:1fr 1fr;gap:8px}.soc a{color:#fff;text-align:center;padding:10px;border-radius:4px;font-weight:600}
.live iframe{width:100%;aspect-ratio:16/9;border:0;border-radius:5px;background:#0a1f4d}
.wx{display:flex;justify-content:space-between;align-items:center;gap:8px}.wx big{display:block;font-size:28px;font-weight:700;color:#0b2a63}.wx small{color:#6b7385;font-size:12px}
.widget ul{list-style:none;margin:0;padding:0}.widget li{padding:7px 0;border-bottom:1px solid #e3e7ef}
footer{background:#0b2a63;color:#fff;padding:18px 0}footer .w{display:flex;justify-content:space-between;flex-wrap:wrap;gap:8px}
.pt-item #home,.pt-static_page #home{display:none}.pt-index #posts{display:none}
#posts{max-width:820px;margin:16px auto;background:#fff;border-radius:6px;padding:16px}
.post-title{font-size:26px;line-height:1.4;color:#0b2a63}.post-body{font-size:16px;line-height:1.9}
.post-footer{color:#6b7385;font-size:12px;margin-top:12px}
@media(max-width:1100px){.g{grid-template-columns:1fr 1fr}.c2{order:-1;grid-column:1/-1}.mainrow{grid-template-columns:1fr}}
@media(max-width:700px){.g{grid-template-columns:1fr}.logo h1{font-size:30px}.hero h2{font-size:19px}}

body.script:
//
(function(){
var C={'देश':'#e11d2e','राजनीति':'#1d6fe0','समाज':'#2e9e4a','खेलकुद':'#7c3aed','अर्थतन्त्र':'#f57c00','प्रविधि':'#0ea5c4','मनोरञ्जन':'#e91e8c','स्थानीय':'#16a34a','विश्व':'#0d9488'};
function nd(s){return String(s).replace(/\d/g,function(d){return '०१२३४५६७८९'.charAt(d)})}
function esc(s){return String(s).replace(/[&<>"']/g,function(c){return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]})}
function $(i){return document.getElementById(i)}
var d=new Date();$('dt').textContent=nd(d.toLocaleDateString('en-GB',{day:'numeric',month:'short',year:'numeric'}));$('yr').textContent=nd(d.getFullYear());
var path=decodeURIComponent(location.pathname),m=path.match(/^\/search\/label\/(.+)$/),label=m?m[1]:'',q=new URLSearchParams(location.search).get('q')||'';
var nv='<a href="/" class="'+(label?'':'on')+'">&#8962; गृहपृष्ठ</a>',cs='';
Object.keys(C).forEach(function(k){var u='/search/label/'+encodeURIComponent(k);nv+='<a href="'+u+'" class="'+(label===k?'on':'')+'">'+k+'</a>';cs+='<a href="'+u+'" style="background:'+C[k]+'">'+k+'</a>'});
$('nav').innerHTML=nv;$('cs').innerHTML=cs;
function ago(t){var h=Math.max(1,Math.round((Date.now()-t)/36e5));return h>=24?nd(Math.floor(h/24))+' दिन अघि':nd(h)+' घण्टा अघि'}
function parse(e){
 var a=(e.link||[]).filter(function(l){return l.rel==='alternate'})[0];
 var labs=(e.category||[]).map(function(c){return c.term});
 var img=e.media$thumbnail?e.media$thumbnail.url.replace(/\/s\d+(-c)?\//,'/s640/'):'';
 if(!img){var mm=((e.content&&e.content.$t)||'').match(/<img[^>]+src="([^"]+)"/);if(mm)img=mm[1]}
 var cat=labs.filter(function(l){return C[l]})[0]||labs.filter(function(l){return !/^(breaking|featured)$/i.test(l)})[0]||'समाचार';
 return {t:e.title.$t,u:a?a.href:'#',l:labs,cat:cat,img:img,d:new Date(e.published.$t).getTime()}}
function im(p,c){var col=C[p.cat]||'#0b2a63';return '<div class="im '+(c||'')+'" style="background-image:'+(p.img?'url('+p.img+')':'linear-gradient(135deg,'+col+',#0b2a63)')+'">'+(p.img?'':esc(p.cat.charAt(0)))+'</div>'}
function bd(p){return '<span class="badge" style="background:'+(C[p.cat]||'#555')+'">'+esc(p.cat)+'</span>'}
function li(p){return '<a class="li" href="'+p.u+'">'+im(p)+'<div>'+bd(p)+'<h4>'+esc(p.t)+'</h4><span class="tm">&#9719; '+ago(p.d)+'</span></div></a>'}
function has(p,k){return p.l.some(function(l){return l.toLowerCase()===k})}
var url='/feeds/posts/default'+(label?'/-/'+encodeURIComponent(label):'')+'?alt=json&max-results=40'+(q?'&q='+encodeURIComponent(q):'');
fetch(url).then(function(r){return r.json()}).then(function(j){
 var P=((j.feed&&j.feed.entry)||[]).map(parse);
 if(!P.length){$('lt').textContent='';$('cd').innerHTML='<p>कुनै समाचार भेटिएन।</p>';return}
 $('lt').innerHTML=P.slice(0,6).map(li).join('');
 var home=!label&&!q;
 $('ch').textContent=label||(q?'खोज नतिजा':'ताजा समाचार');
 var br=P.filter(function(p){return has(p,'breaking')}).slice(0,8);
 if(br.length){$('bk').style.display='block';$('bkt').innerHTML=br.map(function(p){return '<a href="'+p.u+'">'+esc(p.t)+'</a>'}).join(' &nbsp;|&nbsp; ')}
 if(home){
  var hero=P.filter(function(p){return has(p,'featured')})[0]||P[0];
  var side=P.filter(function(p){return p!==hero}).slice(0,3);
  $('hr').innerHTML='<div class="mainrow"><a class="hero" href="'+hero.u+'">'+im(hero)+'<div class="tx"><span class="badge" style="background:#e11d2e">ब्रेकिङ न्युज</span><h2>'+esc(hero.t)+'</h2><span class="tm">'+ago(hero.d)+'</span></div></a><div class="side3">'+side.map(li).join('')+'</div></div>'}
 $('cd').innerHTML=P.slice(0,16).map(function(p){return '<a class="card" href="'+p.u+'">'+im(p)+'<div class="b">'+bd(p)+'<h4>'+esc(p.t)+'</h4><span class="tm">&#9719; '+ago(p.d)+'</span></div></a>'}).join('');
}).catch(function(){$('lt').textContent='समाचार लोड हुन सकेन'});
})();
//
